from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
file=ROOT/'scripts/desktop/composer-context-fixture.tsx';text=file.read_text(encoding='utf-8');assert "action==='messages.list'" in text;text=text.replace("action==='messages.list'","action==='context.chat'")
text=text.replace("fixture.permission=(permission:string)","fixture.sources=(sources:any[])=>setOptions((value:any)=>({...value,sources}));fixture.permission=(permission:string)");file.write_text(text,encoding='utf-8',newline='\n')
file=ROOT/'scripts/desktop/test-composer-context-ui.mjs';text=file.read_text(encoding='utf-8');text=text.replace("const result={title:","const result={owner:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',id:'cccccccc-cccc-4ccc-8ccc-cccccccccccc',kind:'browser',capturedAt:'2026-10-20T12:00:00.000Z',title:")
text=text.replace('Saved context chat Insert recent message excerpt','Saved context chat Attach saved text snapshot')
lines=text.splitlines()
def check(prefix,replacement):
    indexes=[i for i,line in enumerate(lines) if line.startswith(" await check('"+prefix)];assert len(indexes)==1,(prefix,indexes);lines[indexes[0]]=replacement
check('A selected page appends',""" await check('A selected page creates a removable snapshot chip and preserves the latest draft and agent choices',async()=>{await reset();await readTab();await page.evaluate(()=>window.contextFixture.edit('Updated draft while reading'));await resolve();await expect(page.getByRole('textbox',{name:'Message',exact:true})).toHaveValue('Updated draft while reading');await expect(page.getByRole('button',{name:'Remove source Live report',exact:true})).toBeVisible();const state=await page.evaluate(()=>window.contextFixture.state);assert.deepEqual(state.options.sources,[result]);assert.equal(state.options.model,'fixture-model');assert.equal(state.options.provider,'openai-oauth');assert.equal(state.options.permission,'full');assert.equal(state.config.agent.name,'Mira');assert.equal(await page.evaluate(()=>window.contextFixture.calls.filter(c=>c.action==='browser.context').length),1);assert.equal(await page.evaluate(()=>window.contextFixture.calls.filter(c=>['browser.open','chat.start'].includes(c.action)).length),0);await page.getByRole('button',{name:'Remove source Live report',exact:true}).click();await expect(page.getByRole('button',{name:'Remove source Live report',exact:true})).toHaveCount(0);await expect(page.getByRole('textbox',{name:'Message',exact:true})).toHaveValue('Updated draft while reading');});""")
check('Oversized combined context',""" await check('Oversized source text is refused while a long typed draft remains separate',async()=>{await reset();await readTab();await page.evaluate(()=>window.contextFixture.edit('x'.repeat(99990)));await resolve({...result,text:'x'.repeat(16001)});await expect(page.getByText('Invalid selected source.',{exact:true})).toBeVisible();assert.equal((await page.getByRole('textbox',{name:'Message',exact:true}).inputValue()).length,99990);assert.equal(await page.evaluate(()=>window.contextFixture.state.options.sources?.length??0),0);await expect(page.getByRole('button',{name:'Send',exact:true})).toBeEnabled();});""")
check('Saved-chat excerpts carry',""" await check('Saved-chat selection creates an independent snapshot without changing the typed question',async()=>{await reset();await open();await page.getByRole('menuitem',{name:/^Saved context chat Attach saved text snapshot/}).click();const source={...result,kind:'chat',id:'22222222-2222-4222-8222-222222222222',title:'Saved context chat',url:'agentopia-chat://22222222-2222-4222-8222-222222222222',text:'user: MESSAGE-04\\nassistant: MESSAGE-23'};await resolve(source);await expect(page.locator('.composer-add-menu')).toHaveCount(0);await expect(page.getByRole('textbox',{name:'Message',exact:true})).toHaveValue('Keep my draft');await expect(page.getByRole('button',{name:'Remove source Saved context chat',exact:true})).toBeVisible();assert.deepEqual(await page.evaluate(()=>window.contextFixture.state.options.sources),[source]);assert.equal(await page.evaluate(()=>window.contextFixture.calls.filter(row=>row.action==='context.chat').length),1);});""")
check('Typed live-tab selection',""" await check('Typed live-tab selection removes only its query, adds a chip and prevents a pending Enter send',async()=>{await reset();const input=page.getByRole('textbox',{name:'Message',exact:true});await input.fill('Check @Live');await expect(page.getByRole('option',{name:/^Live report/})).toBeVisible();await input.press('Enter');await expect(page.getByText('Reading selected context…',{exact:true})).toBeVisible();await input.press('Enter');assert.equal(await page.evaluate(()=>window.contextFixture.submits),0);await resolve();await expect(input).toHaveValue('Check ');await expect(page.getByRole('button',{name:'Remove source Live report',exact:true})).toBeVisible();assert.deepEqual(await page.evaluate(()=>window.contextFixture.state.options.sources),[result]);assert.equal(await page.evaluate(()=>window.contextFixture.calls.filter(c=>c.action==='browser.context').length),1);});""")
# Late responses are discarded before parsing; preserve these cancellation probes.
extra=""" await check('Source-only messages expose Send, Chat only disables it, and reselection refreshes one chip',async()=>{await reset();await page.evaluate(()=>window.contextFixture.edit(''));await readTab();await resolve();await expect(page.getByRole('button',{name:'Send',exact:true})).toBeEnabled();await readTab();await resolve({...result,text:'UPDATED SNAPSHOT'});assert.equal(await page.evaluate(()=>window.contextFixture.state.options.sources.length),1);assert.equal(await page.evaluate(()=>window.contextFixture.state.options.sources[0].text),'UPDATED SNAPSHOT');await page.evaluate(()=>window.contextFixture.permission('chat'));await expect(page.getByRole('button',{name:'Send',exact:true})).toBeDisabled();await expect(page.getByText('Chat only blocks attachments. Change permissions or remove them before sending.',{exact:true})).toBeVisible();});"""
index=next(i for i,line in enumerate(lines) if line.startswith(' evidence.success=true;'));lines.insert(index,extra);file.write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Context lifecycle tests updated for structured snapshots.')
